from save_review import save
save(896,{2:'火卫一以组建同名的帝国卫队各团而闻名。',5:'名称：火卫一（Phobos；原稿又音译福波斯）。',8:'火卫一第十六团——参加过第十三次黑色远征。'},notes={2:'raising regiments 指征募并组建部队，不是一般培养。此篇未明确叙述其与火星卫星的天体关系，名称沿既有译稿，不据同名擅增位置。'})
save(897,{9:'次星区：现归属不明，原属利拉克次星区。',17:'科尔沃西原名科洛西，曾是帝国的骑士世界。如今，它已沦为恶魔世界，既是恶魔亲王比拉克尔的统治中心，也是科瓦克斯家族混沌骑士的母星。',20:'科洛西是渡鸦家族的母星。在效忠机械教的骑士家族中，渡鸦家族名声显赫，实力与机甲数量都居前列。无人确知它为何拥有如此多的骑士机甲，但最早定居时期的古老记录提到过一项如今早已失传的标准建造模板古科技。或许正是这项神奇技术，加上科洛西丰富的天然资源，让家族建成庞大的骑士大军。也有人认为，早期定居者只是将生产能力集中用于制造骑士机甲。',22:'持续的露天采矿和无休止的工业生产，使科洛西地表的生态严重恶化。少数城市坐落在横贯地表、绵延数百英里的裂隙中，以地热发电维持运转。居民在深层矿井、铸造圣所和营养糊生产槽旁辛劳工作。统治他们的是渡鸦家族贵族；但贵族经常出征，城市的日常管理因而交给下级官员。',24:'这些城市中最宏伟的是堡垒城市“不侵要塞”。在帝国境内，只有芬里斯的长牙堡和泰拉的帝皇宫殿比它更为雄伟。要塞上层穿过科洛西污浊的大气，直达太空；地基则深入星球地壳。名为“超验宝库”的设施就坐落于地基之间，存放渡鸦家族数量庞大的骑士机甲与遗物。',27:'查拉顿战役中，恶魔亲王比拉克尔向科洛西释放黑暗浪潮，使这个世界走向末日。疯狂梦魇、猜疑与成群恶魔接连袭来；遭腐化的骑士又倒戈攻击领主，局势终于崩溃。行星沦陷后，渡鸦家族的幸存者转为一支四处征战的远征军。',32:'“科尔沃西”一名可能取自拉丁学名 Corvus，即包含渡鸦在内的鸦属。这或许影射该世界曾是渡鸦家族的母星，而堕落后由科瓦克斯家族占据。',35:'注1：第七版骑士圣典在介绍达克洛恩男爵时，有一处将行星名拼作 Kollossi。底稿作者认为这很可能是笔误：同书其他地方均写作 Kolossi，下一版圣典重印达克洛恩的描述时也采用 Kolossi。'},notes={17:'Be’lakor 依已核官方定译比拉克尔；原稿比拉克等异写保留于对照。',20:'Questor Mechanicus 是效忠机械教的骑士类别，不是“机械教探索者”。',22:'generatora 疑为 generators 笔误，中文据地热发电语境译；劳工在生产槽设施工作，不是住在粥桶里。',24:'Keep Inviolate 暂译不侵要塞，原“严守不渝”未表达堡垒名称；Vault Transcendent 为地下收藏设施，暂译超验宝库，非地上穹顶。',27:'crusading force 为远征部队，原“运动部队”误译；turned upon 指倒戈袭击，不是简单转向。',35:'保留英文字形，才能看出 Kollossi 与 Kolossi 的差异；源文关于第七版拼写的判断未独立核验。'},terms=[('Korvosi','科尔沃西'),('Kolossi','科洛西'),('Kollossi','科洛西'),('House Raven','渡鸦家族'),('House Korvax','科瓦克斯家族'),('Keep Inviolate','不侵要塞'),('Vault Transcendent','超验宝库'),('Daklorn','达克洛恩'),('Lirac Sub-Sector','利拉克次星区'),('Tethras System','忒特拉斯星系')])
save(898,{11:'第四十一千年之初，但丁统率圣血天使，在泰瑞昂迎战午夜领主与黑暗兄弟会组成的邪恶联军。圣血天使最终取胜。几个世纪后，泰瑞昂重新成为天堂世界，昔日战役只留下首都的一座但丁纪念像。这尊巨大的大理石雕像伸手朝向地平线，纪念但丁当年向如今泰瑞昂居民的先辈施予的仁慈。'},notes={11:'offering mercy to forefathers 是纪念当年的庇护，不是雕像在当下对已故先祖执行某种行动。'},terms=[('Terion','泰瑞昂'),('Brotherhood of Darkness','黑暗兄弟会')])
save(899,{11:'朦胧星曾同时遭到两支军队入侵：一支是战争头目“大杀戮踏人者”率领的欧克部队，另一支是巫师“残酷者”阿努法里斯麾下的混沌军队。血鸦连长阿波罗·狄俄墨得斯率军击败了两位敌酋，解救这颗世界；但战斗结束时，星球已满目疮痍。'},notes={11:'Manstompa Megakilla 暂沿原稿绰号译名，Manstompa为同一人物简称；未另造第二位欧克领袖。'},terms=[('Obscurus (Penal World)','朦胧星（刑罚世界）'),('Manstompa Megakilla','大杀戮踏人者'),('Anupharis the Cruel','残酷者阿努法里斯')])
save(900,{3:'名称：黄泉星（原稿又译阿刻戎）。',9:'黄泉星是一颗神秘而受诅咒的世界，每隔五千年便会从亚空间中现身一次。',12:'第四十一千年，人们发现黄泉星藏有一种据称威力骇人的武器——凯恩之矛，星球由此陷入战火。血鸦战团长加百列·安杰罗斯、比耶-坦方舟世界的大先知玛查，以及欧克军阀“猎头者”戈古兹，分别率军争夺它。',14:'当各方最终找到凯恩之矛时，才发现这是一场混沌阴谋，目的在于释放恶魔大军。危急之下，加百列·安杰罗斯主动驾驶战斗驳船撞入黄泉星的一条裂隙，致使整颗行星解体。'},title='黄泉星 Acheron',notes={3:'沿较早核心行星定译黄泉星，首次保留原稿别名阿刻戎。',12:'Farseer 依已核核心译作大先知；不把比耶-坦误写成人物姓氏。',14:'crashed ... into 表示主动使舰船撞入裂隙，未补写本人一定随舰遇难。'},terms=[('Gorgutz \'Ead \'Unter','猎头者戈古兹')])
save(901,{2:'寒霜星曾是欧克与帝国军队激战的战场。',9:'战斗中，欧克突破了帝国最后一道防线。就在它们准备扩大战果时，新星战士战团将破坏者与肃卫老兵投入冲锋的绿皮面前。战士们在宽达一英里的缺口处顽强抵抗，坚持了六个小时；随后，增援泰坦抵达，以强大火力击退欧克。'},notes={9:'press their attack 指乘势继续进攻，不是此前还未发动攻击。原文 formed a mile-wide breach against the Orks 搭配不清，依后半句防守语境处理为守住一英里宽的缺口，保留英文供核。'},terms=[('Bleakfrost','寒霜星')])
save(902,{11:'塔尔尼斯原是德拉库斯家族帝国骑士的母星。堕天使祖菲尔率恐虐战帮入侵，几乎摧毁了这个家族。混沌战帮却只是第一波来犯之敌；战争头目奈克努恰的大蛮干！也登陆了星球。面对两路入侵，塔尔尼斯似乎已毫无希望，直到提格兰大师率领暗黑天使打击部队前来救援。不过，暗黑天使起初并不知道恐虐战帮的真正目的：他们准备在此完成混沌仪式，把强大的嗜血狂魔法里奥恩从亚空间释放出来。德拉库斯家族最后的幸存骑士沃蒂根逃过了德拉库斯堡之战，转而协助暗黑天使抵御欧克与混沌。塔尔尼斯的“钢铁守望者”阿尔托鲁斯也加入战斗。联军杀死奈克努恰，击退大蛮干！；即使混沌战帮成功召出了法里奥恩，也仍被联军打败。阿尔托鲁斯在夺回德拉库斯堡的战斗中战死，沃蒂根随后继承他的职衔，成为塔尔尼斯的新任钢铁守望者。'},notes={11:'made planetfall 指登陆，不等于已攻陷整颗星球。召唤法里奥恩的是混沌战帮，击败战帮的是帝国联军；原译施受关系混乱，已理清。'},terms=[('Tarnis','塔尔尼斯'),('Zufiel','祖菲尔'),('Nekkruncha','奈克努恰'),('Tigraine','提格兰'),('Felfurion','法里奥恩'),('Vortigan','沃蒂根'),('Altorus','阿尔托鲁斯'),('Iron Warden of Tarnis','塔尔尼斯钢铁守望者'),('Fort Drakkus','德拉库斯堡')])
save(903,{7:'维迪康是一颗遭克拉肯虫巢舰队入侵的丛林世界。',9:'数个卡塔昌帝国卫队团与暗黑天使的一支特遣部队正在奋力保卫维迪康；阿莱托克方舟世界的灵族却决心阻止交战双方中的任何一方获胜。'},notes={9:'neither side 指交战的帝国与泰伦两方，未把后出现的灵族算作其中一方。'},terms=[('Verdicon','维迪康')])
save(904,{3:'名称：拉沙德主星。',9:'拉沙德主星是帝国的一颗世界，曾遭变革神谕战帮入侵。',11:'变革神谕的攻势，还可能切断拉沙德主星向所在星区军队提供的粮食补给。'},title='拉沙德主星 Rashad Prime',notes={11:'sustenance 是维持军队所需的食物供给，原“提供的维持”语义不通。'},terms=[('Rashad Prime','拉沙德主星')])
save(905,{7:'奥罗斯四号是一颗矿场世界，正遭太空死灵入侵。'},notes={7:'本篇拼作 Auros IV；与骑士世界名录的 Aurous IV 是否同一对象尚待核。'},terms=[('Auros IV','奥罗斯四号')])
